-- ============================================================================
-- commerce service consolidated baseline (order + payment + delivery)
-- ============================================================================
-- GENERATED by merging the three pre-merge V1 baselines. Each source service
-- owned its own database and therefore its own copy of the platform tables
-- (outbox_events / idempotency_records / saga_* / dead_letter_events) and, in
-- some cases, the same business table with a DIFFERENT column set. Merging the
-- databases means each table must be emitted exactly once, so:
--
--   * platform tables are emitted once (payment is listed first and owns them);
--   * agent_cod_wallets / rider_earnings use PAYMENT's shape, because
--     V2__cod_wallet_rider_status is written as an additive repair that reads
--     total_cash_collected / total_cash_deposited and then adds delivery's
--     balance / status / updated_at on top;
--   * order_delivery_proofs uses ORDER's OTP shape; V25 adds delivery's
--     notes / signature columns.
--
-- All statements are IF NOT EXISTS / guarded so the file is re-runnable.
-- ============================================================================


-- ---- from payment ----
CREATE TABLE IF NOT EXISTS public.agent_cod_wallets (
    id bigint NOT NULL,
    agent_id bigint NOT NULL,
    total_cash_collected double precision DEFAULT 0.0 NOT NULL,
    total_cash_deposited double precision DEFAULT 0.0 NOT NULL,
    last_reconciled_at timestamp(6) without time zone,
    created_at timestamp(6) without time zone NOT NULL
);

