ALTER TABLE ONLY public.saga_steps
    ADD CONSTRAINT uq_saga_instance_step UNIQUE (saga_instance_id, step_order);
ALTER TABLE ONLY public.saga_instances
    ADD CONSTRAINT uq_saga_instances_saga_id UNIQUE (saga_id);
ALTER TABLE ONLY public.wallet_balances
    ADD CONSTRAINT wallet_balances_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.wallet_transactions
    ADD CONSTRAINT wallet_transactions_pkey PRIMARY KEY (id);
CREATE INDEX IF NOT EXISTS idx_disputes_customer ON public.disputes USING btree (customer_id, status);
CREATE INDEX IF NOT EXISTS idx_disputes_payment ON public.disputes USING btree (payment_id);
CREATE INDEX IF NOT EXISTS idx_dlq_aggregate ON public.dead_letter_events USING btree (aggregate_type, aggregate_id);
CREATE INDEX IF NOT EXISTS idx_dlq_status_created ON public.dead_letter_events USING btree (status, created_at);
CREATE INDEX IF NOT EXISTS idx_idempotency_expires ON public.idempotency_records USING btree (expires_at);
CREATE INDEX IF NOT EXISTS idx_outbox_aggregate ON public.outbox_events USING btree (aggregate_type, aggregate_id);
CREATE INDEX IF NOT EXISTS idx_outbox_status_created ON public.outbox_events USING btree (status, created_at);
CREATE INDEX IF NOT EXISTS idx_payment_purpose ON public.payments USING btree (purpose);
CREATE INDEX IF NOT EXISTS idx_payment_transaction ON public.payments USING btree (transaction_id);
CREATE INDEX IF NOT EXISTS idx_payments_customer ON public.payments USING btree (customer_id, created_at);
CREATE INDEX IF NOT EXISTS idx_payments_order ON public.payments USING btree (order_id);
CREATE INDEX IF NOT EXISTS idx_payments_status ON public.payments USING btree (status);
CREATE INDEX IF NOT EXISTS idx_saga_instance_status ON public.saga_steps USING btree (saga_instance_id, status);
CREATE INDEX IF NOT EXISTS idx_saga_steps_pending ON public.saga_steps USING btree (status, step_order);
CREATE INDEX IF NOT EXISTS idx_saga_type_status ON public.saga_instances USING btree (saga_type, status);
CREATE INDEX IF NOT EXISTS idx_settlement_restaurant ON public.restaurant_settlements USING btree (restaurant_id);
CREATE INDEX IF NOT EXISTS idx_wallet_tx_customer ON public.wallet_transactions USING btree (customer_id, created_at);
ALTER TABLE ONLY public.disputes
    ADD CONSTRAINT disputes_payment_id_fkey FOREIGN KEY (payment_id) REFERENCES public.payments(id);
ALTER TABLE ONLY public.dunning_runs
    ADD CONSTRAINT dunning_runs_payment_id_fkey FOREIGN KEY (payment_id) REFERENCES public.payments(id);
ALTER TABLE ONLY public.saga_steps
    ADD CONSTRAINT fk_saga_steps_instance FOREIGN KEY (saga_instance_id) REFERENCES public.saga_instances(id) ON DELETE CASCADE;
ALTER TABLE ONLY public.restaurant_settlements
    ADD CONSTRAINT restaurant_settlements_settlement_run_id_fkey FOREIGN KEY (settlement_run_id) REFERENCES public.settlement_runs(id);

